"""Derive Cycle 2 accounting and analysis without changing Cycle 1 decisions."""
import csv,json,hashlib,re
from pathlib import Path
from collections import Counter
from datetime import datetime,timezone
R=Path(__file__).resolve().parents[1];E=R/'evidence';stamp=datetime.now(timezone.utc).isoformat(timespec='seconds')
def read(n):return list(csv.DictReader((E/n).open()))
def write(n,rows):
 with (E/n).open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
records=read('records.csv');screen=read('screening.csv');dup=read('duplicates.csv');versions=read('version_review_audit.csv');ex=read('extraction.csv');qa=read('quality.csv');forms=read('study_extraction_form.csv');checks=read('fulltext_checks.csv');sb=read('snowballing.csv')
canonical={r['canonical_record_id'] for r in records};assert len(canonical)==len(screen)==2247
assert {r['record_id'] for r in screen}==canonical
assert all(r['final_decision']=='pending' for r in screen)
votes=Counter(r['reviewer_1_vote'] for r in screen)
assert votes=={'exclude_recommendation':1181,'retain_or_uncertain':1066},votes
counts=json.loads((E/'prisma_counts.json').read_text());counts.update(occurrences=len(records),by_source=dict(Counter(r['database'] for r in records)),exact_duplicate_occurrences=len(dup),records_after_exact_linkage=len(canonical),possible_version_pairs=len(versions),preliminary_recommendations=sum(votes.values()),preliminary_exclusion_recommendations=votes['exclude_recommendation'],preliminary_retain_or_uncertain=votes['retain_or_uncertain'],first_recommendations_pending=0,final_screened=None,final_included=None,version_pair_dispositions=dict(Counter(r['audit_disposition'] for r in versions)))
assert len(records)-len(dup)==len(canonical)
(E/'prisma_counts.json').write_text(json.dumps(counts,indent=2)+'\n')
# Every analysis statement is bounded by registered observations and pending validation.
rows=[]
def add(kind,id,topic,claim,reports='',outcomes='',anchor='',limit='',confidence='Limited; first-review evidence only'):
 rows.append(dict(analysis_id=id,kind=kind,topic=topic,interim_analysis=claim,report_ids=reports,outcome_ids=outcomes,source_anchor=anchor,limitation_or_required_check=limit,confidence=confidence,final_status='pending human validation',prepared_at_utc=stamp))
add('taxonomy','T01','Temporal sharing / time-slicing','Serial execution opportunities can reduce simultaneous competition, while switching and model movement add latency. PipeSwitch pipelines transfers when switching from training to inference; it is a specialized temporal design, not evidence that all driver time-slicing behaves identically.','GB-P004','GB-O005;GB-O007;GB-O012;GB-O013','p508 section6.1; p509 Table3','Mixed-workload eligibility and runtime integration need validation.')
add('taxonomy','T02','MPS concurrency','MPS permits concurrent process work with tunable compute quotas; adaptive allocation addresses interference rather than establishing a security boundary. VastPipe and iGniter supply local examples, and gpulets combines this with temporal batching.','GB-P001;GB-P002;GB-P003','GB-O001;GB-O002;GB-O003;GB-O004;GB-O006','P001 pp457-458 Fig14; P002 p822 section5.2 Fig13; p823 section5.3 Fig17; P003 p203 Fig7','Quota, GPU, memory and workload determine applicability; no universal throughput or p99 guarantee.')
add('taxonomy','T03','MIG spatial partitions','MIG is a spatial hardware-partition category in the submitted protocol and vendor context. None of the five active checked report forms supplies a MIG outcome; comparative performance, memory efficiency and tested fault/security isolation remain unestablished here.','','','Submitted protocol taxonomy; NVIDIA MIG context reference','Context definition only. Retrieve and appraise relevant primary outcomes before comparing with MPS.', 'Insufficient extracted primary evidence')
add('taxonomy','T04','API interception / remoting','Interception is an implementation layer; remoting additionally redirects calls to an execution endpoint. REEF intercepts/schedules work, but its checked results do not evaluate a remote multi-tenant endpoint. No API-remoting outcome is available in the current checked set.','GB-P005','','P005 pp539-542; study_extraction_form.csv','Do not relabel local API interception as remote execution or infer network overhead.', 'Insufficient extracted remoting evidence')
add('taxonomy','T05','Hybrid methods','gpulets combines MPS space sharing with temporal batching. REEF combines reset-based preemption with dynamic kernel padding to reclaim best-effort capacity around real-time work. These are overlapping design attributes rather than mutually exclusive study bins.','GB-P003;GB-P005','GB-O006;GB-O018;GB-O019;GB-O023;GB-O024','P003 pp201-207; P005 p549 section7.2/Fig11','Hybrid benefits require their scheduler, workload and driver/runtime assumptions.')
comparisons=[
('C01','Adaptive MPS','A100; VGG16 plus GoogLeNet: tuned MPS throughput 2.7x versus no MPS and 1.5x versus default MPS.','GB-P001','GB-O001;GB-O002','pp457-458 Fig14 discussion','Exact quota/batch and local tail-latency outcomes remain unextracted; throughput is not a measured utilization percentage.'),
('C02','Interference-aware MPS provisioning','V100; batch3 prediction check has 1.53-5.02% latency prediction error. W1 recovery example initially has p99 15.6ms against a 10ms SLO; transient violation remains visible.','GB-P002','GB-O003;GB-O004','p822 section5.2 Fig13; p823 section5.3 Fig17 prose','Prediction accuracy is not throughput gain and does not guarantee an always-satisfied SLO; software/driver details unresolved.'),
('C03','MPS plus temporal batching','RTX2080Ti paired-model check: 90% of model pairs have overhead below 17.66%. This is a distribution across model pairs, not request p90.','GB-P003','GB-O006','p203 Fig7; p207 Tables2-3','Local result cannot establish end-to-end multi-GPU scale gains. No extracted security/fault experiment.'),
('C04','Pipelined temporal switching','At inference batch8 / training32, 100-run mean added latency over a ready model is 6.01ms versus MPS 307.02ms for ResNet152 on V100; T4 counterpart 5.57ms versus 259.20ms. Other model/device rows remain in the outcome register.','GB-P004','GB-O005;GB-O007;GB-O012;GB-O013','p508 section6.1; p509 Table3','MPS comparator incurs unified-memory swapping under memory pressure. Additional mean latency is neither total latency nor p99; mixed workload requires eligibility validation.'),
('C05','Preemption plus kernel padding','MI50: DISB A/B throughput 1.60x / 1.14x versus real-time only, with 0.5% / 1% real-time latency overhead. Five-RT/five-BE DISB D/E throughput is 3x / 2.96x versus RT-only but about 25% below GPUStreams. Apollo trace total RT+BE throughput is 7.7x with under 2% RT latency overhead.','GB-P005','GB-O018;GB-O019;GB-O020;GB-O021;GB-O023;GB-O024;GB-O025;GB-O026','p548 Table2; p549 section7.2/Fig11','These are separate workloads and baseline denominators, not one pooled gain; trace replay is not a production deployment. Idempotence and customized runtime/driver constrain use.')]
for id,t,c,p,o,a,l in comparisons:add('comparison',id,t,c,p,o,a,l)
add('tradeoff','D01','Useful work versus latency predictability','The MPS throughput improvement in VastPipe and REEF reclaiming BE work support investigating spare-capacity use. The iGniter transient SLO violation and REEF cost versus GPUStreams show that throughput and latency objectives require separate acceptance tests.','GB-P001;GB-P002;GB-P005','GB-O001;GB-O004;GB-O023;GB-O024','As anchored in C01/C02/C05','No common utilization percentage, arrival process or end-to-end p99 comparison is available.')
add('tradeoff','D02','Memory pressure versus switching cost','PipeSwitch reduces added switching latency against its memory-swapping MPS configuration. The cost is a pipelined transfer/runtime architecture and a workload-specific applicability decision.','GB-P004','GB-O005;GB-O007;GB-O012;GB-O013','p508 section6.1; p509 Table3','Do not extrapolate to memory-resident inference-only MPS tenants.')
add('tradeoff','D03','Isolation versus resource flexibility','Performance interference is evaluated in MPS-based sharing and REEF scheduling, but lower interference does not establish confidentiality, malicious-tenant protection or fault containment. MIG is a distinct partition candidate; its empirical trade-off cannot be ranked from the active evidence.','GB-P002;GB-P003;GB-P005','GB-O004;GB-O006;GB-O019','Q9 items; study forms; outcome anchors','No checked primary comparison supports a security or fault-isolation winner.')
add('tradeoff','D04','Scalability versus integration overhead','gpulets requires coordinated allocation, batching and proxy reorganization; REEF requires kernel/preemption support; PipeSwitch requires model-transfer orchestration. Tenant-count and platform results are configuration-specific, and integration effort has no common numeric scale in the extraction register.','GB-P003;GB-P004;GB-P005','GB-O006;GB-O023;GB-O024','P003 p207 Fig11/Table2; P004 p508; P005 pp548-549','Multi-server context is not a within-device scaling curve. Do not claim portable low implementation cost.')
add('tradeoff','D05','Performance versus energy / reliability','Throughput and latency observations do not determine energy per request or resilience under device/process faults. These fields remain not extracted in the study forms, so the recommendation cannot promise energy savings or recovery guarantees.','GB-P001;GB-P002;GB-P003;GB-P004;GB-P005','','study_extraction_form.csv energy/reliability/security fields','Not extracted means unchecked; it is not a claim that the papers never report the property.', 'Insufficient comparable evidence')
add('conflict','F01','MPS improves throughput versus MPS has high latency','VastPipe reports a tuned MPS throughput benefit while PipeSwitch reports high MPS added latency. This is apparent disagreement across different questions: A100 co-inference throughput versus V100/T4 memory-constrained training/inference switching. Baseline, memory behavior, GPU and measured statistic differ. A matched contradiction is not established.','GB-P001;GB-P004','GB-O001;GB-O002;GB-O005;GB-O007','P001 pp457-458; P004 p509 Table3','A matched test must hold GPU, models, resident memory, batching, quotas, load and latency statistic fixed.')
add('conflict','F02','REEF helps RT+BE throughput yet trails GPUStreams','REEF DISB D/E increases throughput over RT-only but is about 25% below GPUStreams. Both statements can hold because the denominators and latency priorities differ. This is a within-study trade-off rather than evidence of a universally superior scheduler.','GB-P005','GB-O023;GB-O024','p549 section7.2/Fig11','Retain RT-only and GPUStreams baselines separately; no cross-paper pooling.')
add('conflict','F03','Accurate latency model versus an SLO violation','iGniter prediction-error results and a recovery example with an initial p99 violation measure different conditions. Small modeling error does not prove zero transient violations under changes.','GB-P002','GB-O003;GB-O004','p822 section5.2 Fig13; p823 section5.3 Fig17 prose','Check load, model and recovery interval before claiming steady-state predictability.')
add('conflict','F04','Pair CDF versus request percentile','The gpulets 90%-of-pairs result describes which co-located model combinations have bounded overhead. Treating it as request p90 would create a false comparison with iGniter p99. No contradiction between those statistics is established.','GB-P003;GB-P002','GB-O006;GB-O004','P003 p203 Fig7; P002 p823 section5.3 Fig17','Use separate populations and units; mean added latency in PipeSwitch is another distinct estimand.')
add('rq','RQ1','Mechanisms and classification','The checked set supports temporal switching, MPS allocation and hybrids at runtime/scheduler layers. MIG and API remoting remain taxonomy categories with no checked primary outcome in this set. REEF interception is local and not evidence of remoting.','GB-P001;GB-P002;GB-P003;GB-P004;GB-P005','','T01-T05; study forms','Taxonomy coverage is incomplete and does not establish prevalence among all eligible studies.')
add('rq','RQ2','Metrics and comparability','Outcomes include baseline-relative throughput, prediction error, p99 recovery latency, across-pair interference CDF and mean added switching latency. Only matched within-paper contrasts are interpreted numerically; no pooled speedup or common ranking is defensible.','GB-P001;GB-P002;GB-P003;GB-P004;GB-P005','GB-O001;GB-O003;GB-O004;GB-O005;GB-O006;GB-O025','C01-C05; F01-F04','Current evidence does not provide comparable energy, security or utilization-percentage estimates.')
add('rq','RQ3','Conditions affecting outcomes','GPU architecture, model mix, memory pressure, batch/load, tenant count and baseline alter what a result means. Observed settings range from A100 paired inference to V100 provisioning, RTX2080Ti model pairs, V100/T4 switching and MI50 RT/BE workloads. No controlled cross-platform causal effect is inferred.','GB-P001;GB-P002;GB-P003;GB-P004;GB-P005','GB-O001;GB-O004;GB-O006;GB-O012;GB-O024','C01-C05; study forms','Unextracted configuration fields constrain transfer to another OS/driver/runtime and service load.')
add('rq','RQ4','Isolation, costs and conflicting results','The evidence supports analyzing performance interference and scheduling overhead. It does not establish security/fault isolation. Memory-swapping baseline behavior, preemption assumptions and custom runtime integration explain conditional costs; apparent MPS disagreement lacks a matched cross-study test.','GB-P002;GB-P003;GB-P004;GB-P005','GB-O004;GB-O006;GB-O007;GB-O023','D02-D05; F01-F04; Q9 items','Quality forms are unreconciled, and missing properties must not be treated as zero cost.')
add('rq','RQ5','Conditional engineering choice','For trusted, throughput-oriented co-inference, evaluate adaptive MPS with local tail-latency tests. For RT/BE mixes with supported kernels, evaluate preemption/hybrid scheduling. For memory-constrained mixed training/inference, evaluate pipelined switching if eligible. For strict security/fault boundaries or remoting, current extracted evidence is insufficient for a selection.','GB-P001;GB-P002;GB-P004;GB-P005','GB-O001;GB-O004;GB-O005;GB-O018;GB-O023','R01-R05','These are candidates for controlled validation, not production guarantees or a final included-study synthesis.')
add('recommendation','R01','Trusted co-inference; throughput priority','Candidate: adaptive MPS allocation. Expected direction: more useful throughput in the checked A100 pair; sacrifice quota tuning and potential interference. Alternative: temporal/hybrid scheduling when latency transients dominate. Acceptance: replay actual arrival/batch/model mix and verify per-tenant p99, SLO misses and memory headroom.','GB-P001;GB-P002','GB-O001;GB-O002;GB-O004','P001 pp457-458; P002 recovery example','No universal 2.7x prediction. Target GPU/software compatibility and independent source checks remain open.')
add('recommendation','R02','RT / BE inference; latency priority','Candidate: preemption plus concurrency/padding when kernels satisfy reset/idempotence assumptions and the runtime can be changed. Expected direction: reclaim BE capacity with small reported RT overhead in the checked MI50 tests. Sacrifice: lower throughput versus GPUStreams in DISB D/E and integration constraints. Alternative: simpler isolation/serialized scheduling when those assumptions fail.','GB-P005','GB-O018;GB-O019;GB-O023;GB-O024','p549 section7.2/Fig11','Verify p99/SLO over bursts, cancellation and faults; reported aggregate overhead is not an SLA guarantee.')
add('recommendation','R03','Memory-constrained training / inference switching','Candidate: pipelined temporal switching, conditional on mixed-workload eligibility. Expected direction: lower mean added switching latency than the checked unified-memory MPS comparator. Sacrifice: runtime/model-transfer integration. Alternative: tuned MPS when models fit and concurrency is beneficial.','GB-P004','GB-O005;GB-O007;GB-O012;GB-O013','p508 section6.1; p509 Table3','Validate resident-memory budget, model transfer path, all percentiles and inference-only applicability.')
add('recommendation','R04','Strong security / fault isolation required','No evidence-backed winner can be selected from the five checked forms. Evaluate a hardware-partition candidate such as MIG only after primary isolation and performance evidence is extracted and the actual threat model is tested. Use dedicated resources where local risk acceptance requires separation; that is a risk-control option, not a measured superiority claim.','','','T03; D03; Q9 items','Current evidence supplies no tested malicious-tenant or fault-containment comparison.', 'Insufficient extracted evidence')
add('recommendation','R05','Remote endpoint or deployment portability required','No API-remoting selection or quantified network-cost claim is supported. Retrieve an eligible shared-endpoint evaluation and check network path, isolation, tenancy and runtime compatibility before selection. REEF local interception cannot fill this evidence gap.','GB-P005','','T04; study forms','No remoting outcomes or common implementation-effort measurements in active registers.', 'Insufficient extracted evidence')
for id,topic,claim,limit in [
('G01','Matched mechanism comparisons','The extracted set lacks a matched MIG/MPS/temporal/remoting benchmark with common hardware, model mix, memory, load and latency definitions.','This is a gap in the current extracted evidence, not proof of absence across the literature.'),
('G02','Tail latency under dynamics','Transient SLO behavior needs separate attention from mean overhead, pair CDFs and throughput. A common burst/overload/reconfiguration protocol would make predictability comparisons interpretable.','Do not infer request p99 from gpulets pair quantiles or REEF aggregate overhead.'),
('G03','Security, faults and energy','No comparable extracted energy-per-request, attack-isolation or injected-fault outcome supports a recommendation on these priorities.','Complete unchecked fields and retrieve eligible evaluations before calling an absence not reported.'),
('G04','Scalability and portability','Within-device tenant/load scaling, OS/driver sensitivity and implementation effort need consistent extraction; multi-GPU context cannot substitute for local scaling evidence.','No extrapolation from MI50/ROCm to NVIDIA MPS or newer hardware without validation.'),
('G05','Evidence completeness and replication','Five preliminary report forms cannot establish the instructor target of 15-20 eligible primary studies or robust family coverage. Broader full-text eligibility, extraction, version mapping and independent checks remain necessary.','The review is interim; study count and certainty must be revised after validation.')]:add('gap',id,topic,claim,'','','Current study forms; quality/extraction registers',limit,'Review-scope observation')
for id,t,c,l in [
('V01','Selection and database coverage','ACM provenance is partly recovered, ScienceDirect is deferred and shared IEEE/Springer imports are attributed. Original hashes and explicit cutoff/deviation logs reduce silent changes.','Search mapping, older MPS lanes and the 68 staged identifiers remain unresolved; completeness is not established.'),
('V02','Screening judgment','All recommendations remain preliminary; the 1066 candidate queue and 127 sampled exclusions are exposed for validation. Existing Rameen ACM work is preserved without claiming new independent votes.','No independent-consensus sensitivity analysis or final exclusion rate can be claimed.'),
('V03','Extraction and reporting bias','Exact outcome IDs, source anchors, baselines and caveats permit verification. Five bounded checks are a purposive subset, and first-review QA is not independent reconciliation.','Positive headline outcomes may overrepresent available sources. Do not generalize effect prevalence.'),
('V04','Metric and configuration heterogeneity','Within-study contrasts are separated from descriptive cross-study comparisons. Mean added latency, p99, pair CDF, prediction error and RT+BE throughput retain different meanings.','No meta-analysis, pooled speedup or causal GPU-platform comparison is justified.'),
('V05','Study/report identity','Applied duplicates and 41 audited possible pairs remain separate; three identity and three companion proposals are not applied.','Five paper identities and REEF conference/journal preference require reconciliation before study-level counting.'),
('V06','Language, time and publication bias','English primary reports and documented 2020-2026 cutoffs follow the protocol, with explicit seminal exceptions required.','Publication bias is not quantified; older-search coverage and unverified dates can omit relevant evidence.'),
('V07','External validity and missing outcomes','Hardware/software, model/load and source-specific caveats accompany every comparison; gaps are stated as current extraction limits.','The checked tasks do not establish production performance, security, fault containment, energy savings or portability.')]:add('validity',id,t,c,'','','Cycle 1 provenance and current evidence registers',l,'Review-scope observation')
# Resolve every outcome-linked statement directly to immutable Cycle 1 anchors.
lookup={r['outcome_id']:r for r in ex}
for row in rows:
 linked=[lookup[x] for x in row['outcome_ids'].split(';') if x]
 if linked:row['source_anchor']='; '.join(dict.fromkeys(r['report_id']+' '+r['source_anchor'] for r in linked))
write('cycle2_analysis.csv',rows)
for kind in {r['kind'] for r in rows}:write('cycle2_'+kind+'.csv',[r for r in rows if r['kind']==kind])
# Retain every existing workbook sheet; append derived Cycle 2 views.
wi=json.loads((R/'task2/tracker/workbook_input.json').read_text())
for kind,name in [('taxonomy','Taxonomy'),('comparison','Comparative matrix'),('tradeoff','Trade-offs'),('conflict','Conflicting evidence'),('rq','RQ synthesis'),('recommendation','Recommendations'),('gap','Evidence gaps'),('validity','Validity')]:wi['sheets'][name]=[r for r in rows if r['kind']==kind]
(R/'task2/tracker/workbook_input.json').write_text(json.dumps(wi,ensure_ascii=False))
print(json.dumps({'counts':counts,'analysis_rows':len(rows),'kinds':dict(Counter(r['kind'] for r in rows))},indent=2))
